# BEFORE: the same two checks inlined in both flows
def check_user_before(email, age):
    errors = []
    if "@" not in email or "." not in email.split("@")[-1]:
        errors.append("bad email")
    if age < 18:
        errors.append("under 18")
    return errors

def check_store_before(email, age):
    errors = []
    if "@" not in email or "." not in email.split("@")[-1]:
        errors.append("bad email")
    if age < 18:
        errors.append("under 18")
    return errors + (["store ok"] if not errors else [])

# AFTER: shared checks extracted; each flow keeps its own extras
def validate_contact(email, age):
    errors = []
    if "@" not in email or "." not in email.split("@")[-1]:
        errors.append("bad email")
    if age < 18:
        errors.append("under 18")
    return errors

def check_user_after(email, age):
    return validate_contact(email, age)

def check_store_after(email, age):
    errors = validate_contact(email, age)
    return errors + (["store ok"] if not errors else [])

