import itertools

# BEFORE: the happy path is four levels deep
def eligible_before(member, active, cart, coupon):
    if member:
        if active:
            if cart >= 5000:
                if coupon:
                    return "20% off"
                else:
                    return "10% off"
            else:
                return "cart too small"
        else:
            return "inactive"
    else:
        return "not a member"

# AFTER: each rejection is a guard; the reward falls through
def eligible_after(member, active, cart, coupon):
    if not member:
        return "not a member"
    if not active:
        return "inactive"
    if cart < 5000:
        return "cart too small"
    if coupon:
        return "20% off"
    return "10% off"

