# BEFORE: errors raised from inside the nesting
def parse_before(line):
    parts = line.split("=")
    if len(parts) == 2:
        key = parts[0].strip()
        if key:
            value = parts[1].strip()
            if value:
                return (key, value)
            else:
                raise ValueError("empty value")
        else:
            raise ValueError("empty key")
    else:
        raise ValueError("expected key=value")

# AFTER: same checks, same order, as guards
def parse_after(line):
    parts = line.split("=")
    if len(parts) != 2:
        raise ValueError("expected key=value")
    key = parts[0].strip()
    if not key:
        raise ValueError("empty key")
    value = parts[1].strip()
    if not value:
        raise ValueError("empty value")
    return (key, value)

def outcome(fn, line):
    try:
        return ("ok", fn(line))
    except ValueError as e:
        return ("error", str(e))

