    print(repr(l), "->", o)
print("identical:", before == after)

STATUSES = ["placed", "paid", "shipped", "delivered", "cancelled"]
EVENTS = ["pay", "ship", "deliver", "cancel", "refund"]

# BEFORE: nested by status, then event
def transition_before(status, event):
    if status == "placed":
        if event == "pay":
            return "paid"
        if event == "cancel":
            return "cancelled"
        return "invalid"
    if status == "paid":
        if event == "ship":
            return "shipped"
        if event == "refund":
            return "refunded"
        return "invalid"
    if status == "shipped":
        if event == "deliver":
            return "delivered"
        return "invalid"
    if status == "delivered":
        if event == "refund":
            return "refunded"
        return "invalid"
    return "invalid"

# AFTER: one guard per legal transition, one fall-through
def transition_after(status, event):
    if status == "placed" and event == "pay":
        return "paid"
    if status == "placed" and event == "cancel":
        return "cancelled"
    if status == "paid" and event == "ship":
        return "shipped"
    if status == "paid" and event == "refund":
        return "refunded"
    if status == "shipped" and event == "deliver":
        return "delivered"
    if status == "delivered" and event == "refund":
        return "refunded"
    return "invalid"

