SALES = [120, 80, 200, 50, 300]
THRESHOLD = 350

# BEFORE: the loop, untidy names
def first_day_before(sales, t):
    s = 0
    for i, x in enumerate(sales):
        s += x
        if s > t:
            return i
    return -1

# AFTER: same loop, honest names - early exit and state kept
def first_day_after(sales, threshold):
    running_total = 0
    for day_index, amount in enumerate(sales):
        running_total += amount
        if running_total > threshold:
            return day_index
    return -1

# The lazy functional alternative: accumulate + next also stops early
def first_day_functional(sales, threshold):
    return next((i for i, total in enumerate(accumulate(sales))
                 if total > threshold), -1)

